    nets = []
    lens = []
    hops = []
    seen = set()
    for st in parsed_stages:
        for nd_ in st:
            for (rlen, rnet, h) in nd_[3]:
                if (rnet, rlen) in seen:
                    return None
                seen.add((rnet, rlen))
                nets.append(rnet)
                lens.append(rlen)
                hops.append(h)
