    nets_s = [nets[i] for i in order]
    lens_s = [lens[i] for i in order]
    hops_s = [hops[i] for i in order]
    default_hop = None
    for i in range(len(nets_s)):
        if lens_s[i] == 0:
            default_hop = hops_s[i]
    exp_stages, exp_used = compute_layout(nets_s, lens_s, hops_s, cuts)
    # compare node sets, rule sets and edge sets
    for si in range(len(cuts) - 1):
        a = parsed_stages[si]
        bb = exp_stages[si]
        if len(a) != len(bb):
            return None
        for j in range(len(a)):
            if a[j][0] != bb[j][0]:
                return None
            if sorted(a[j][3]) != sorted(bb[j][3]):
                return None
            ea = sorted(a[j][4])
            eb = sorted(bb[j][4])
            if ea != eb:
                return None
