    for si in range(len(cuts) - 1):
        e = cuts[si + 1]
        eterm = 4 + (e - cuts[si] + 7) // 8
        u = 0
        for nd_ in parsed_stages[si]:
            acc8 = 0
            for (rlen, rnet, h) in nd_[3]:
                acc8 += (rlen - cuts[si] + 7) // 8
            u += node_cost(len(nd_[3]), acc8, len(nd_[4]), eterm)
        if u != used[si]:
            return None
    pn, pd = peak_ratio(used, caps)
    if pn != peak['num'] or pd != peak['den']:
        return None
    if used[0] > caps[0]:
        return None
    for i in range(len(caps)):
        if used[i] > caps[i]:
            return None
    return {'cuts': cuts, 'stages': parsed_stages, 'caps': caps}


def do_lookup(req):
    if set(req.keys()) != {'op', 'image', 'addresses'}:
        return None
    img = req['image']
    st = check_image(img)
    if st is None:
        return None
    addrs = req['addresses']
    if not isinstance(addrs, list) or len(addrs) > 20000:
        return None
    vals = []
    for a in addrs:
        if not isinstance(a, str):
            return None
        v = parse_addr(a)
        if v is None:
            return None
        vals.append(v)
    cuts = st['cuts']
    stages = st['stages']
    S = len(cuts) - 1
    answers = []
    for v in vals:
        best_len = -1
        best_hop = None
        cur = 0
        for i in range(S):
            nodes = stages[i]
            if cur >= len(nodes):
                break
            nd_ = nodes[cur]
            b = cuts[i]
            e = cuts[i + 1]
            for (rlen, rnet, h) in nd_[3]:
                if rlen > best_len and (v >> (128 - rlen)) == (rnet >> (128 - rlen)):
                    best_len = rlen
                    best_hop = h
            if i == S - 1:
                break
            sh = 128 - e
            key = v >> sh
            nxt = -1
            for (k, ch) in nd_[4]:
                if k == key:
                    nxt = ch
                    break
                if k > key:
                    break
            if nxt < 0:
                break
            cur = nxt
        if best_len < 0:
            answers.append({'hop': None, 'prefix_length': None})
        else:
            answers.append({'hop': best_hop, 'prefix_length': best_len})
    return {'status': 'ok', 'answers': answers}

# ------------------------------------------------------------------- main ----


def process(obj):
    op = obj.get('op')
    if op == 'compile':
        return do_compile(obj)
    if op == 'lookup':
        return do_lookup(obj)
    return None


def main():
    w = sys.stdout
    for raw in sys.stdin.buffer:
        if raw.endswith(b'\n'):
            raw = raw[:-1]
        obj = parse_request_line(raw)
        resp = None
        if obj is not None:
            try:
                resp = process(obj)
            except Exception:
                resp = None
        if resp is None:
            resp = {'status': 'invalid'}
        w.write(json.dumps(resp, separators=(',', ':')))
        w.write('\n')
    w.flush()


if __name__ == '__main__':
    sys.setrecursionlimit(10000)
    main()
