#!/usr/bin/env python3
"""Launcher: build the native core if needed, then run the pipeline tool."""

import hashlib
import os
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))


def build():
    src = os.path.join(HERE, 'core.c')
    try:
        with open(src, 'rb') as f:
            data = f.read()
    except OSError:
        return None
    tag = hashlib.sha256(data).hexdigest()[:16]
    cands = [os.path.join(HERE, 'build'), tempfile.gettempdir(), '/dev/shm']
    soname = 'scamp_core_%s.so' % tag
    for d in cands:
        so = os.path.join(d, soname)
        try:
            if os.path.exists(so) and os.path.getsize(so) > 0:
                return so
        except OSError:
            continue
    cc = os.environ.get('CC') or 'cc'
    for d in cands:
        so = os.path.join(d, soname)
        try:
            os.makedirs(d, exist_ok=True)
            tmp = so + '.tmp%d' % os.getpid()
            r = subprocess.run([cc, '-O2', '-fPIC', '-shared', '-o', tmp, src],
                               stdout=subprocess.DEVNULL,
                               stderr=subprocess.DEVNULL, timeout=180)
            if r.returncode == 0 and os.path.exists(tmp):
                os.replace(tmp, so)
                return so
            try:
                os.unlink(tmp)
            except OSError:
                pass
        except Exception:
            continue
    return None


def main():
    so = build()
    if so:
        os.environ['SCAMP_CORE'] = so
    else:
        os.environ.pop('SCAMP_CORE', None)
    sys.path.insert(0, HERE)
    import main
    main.main()


if __name__ == '__main__':
    main()
