    k = rng.randrange(14)
    try:
        if k == 0: im['used_bits'][rng.randrange(len(im['used_bits']))] += 64
        elif k == 1: im['peak']['num'] += 1
        elif k == 2: im['cuts'][rng.randrange(1, len(im['cuts']))] += 1
        elif k == 3:
